use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn is_min_index(a: Seq<i8>, idx: nat, len: nat) -> bool
    recommends
        idx < len,
        len > 0,
{
    &&& forall|j: nat| j < len ==> a[idx] <= a[j]
    &&& forall|j: nat| j < idx ==> a[j] > a[idx]
}

fn nanargmin(a: Vec<i8>) -> (result: usize)
    requires
        a.len() > 0,
    ensures
        result < a.len(),
        is_min_index(a@, result as nat, a.len() as nat),
{
    let mut min_idx: usize = 0;
    let mut i: usize = 1;
    
    while i < a.len()
        invariant
            0 <= min_idx < a.len(),
            0 < i <= a.len(),
            // min_idx points to the minimum in the prefix [0, i)
            forall|j: nat| j < i ==> a@[min_idx as nat] <= a@[j],
            // And it's the first occurrence in that prefix
            forall|j: nat| j < min_idx as nat ==> a@[j] > a@[min_idx as nat],
        decreases
            a.len() - i,
    {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
        i = i + 1;
    }
    
    min_idx
}

} // verus!

